function divideRect(x, y, w, h, n, dir) {
	if (n <= 0) return;
	let side = (h > w) ? w : h;
	let sqX, sqY;
	let nextX, nextY, nextW, nextH;
	if (h > w) {
		nextW = w;
		nextH = h - w;
		nextX = x;
		sqX = x;

		if (dir === 0) {
			sqY = y + (h / 2) - (side / 2);
			nextY = y - (w / 2);
		} else {
			sqY = y - (h / 2) + (side / 2);
			nextY = y + (w / 2);
		}

	} else {
		nextH = h;
		nextW = w - h;
		nextY = y;
		sqY = y;
		if (dir === 1) {
			sqX = x - (w / 2) + (side / 2);
			nextX = x + (h / 2);
		} else {
			sqX = x + (w / 2) - (side / 2);
			nextX = x - (h / 2);
		}
	}

	let sd = int(map(n, 12, 1, 6, 1));
	generateElements(sqX, sqY, side, dir + 1, sd)
	divideRect(nextX, nextY, nextW, nextH, n - 1, (dir + 1) % 4);
}

function generateElements(x, y, w, dir, sd) {
	applyRandomStyle();
	square(x, y, w);

	let shapeDensity = sd;


	stroke('#ffffff');
	strokeWeight(height * 0.0025);
	drawArcElement(x, y, w, dir);

	if (w < height * 0.04) return;

	for (let i = 0; i < shapeDensity; i++) {
		let type = ceil(random(4));
		applyRandomStyle();
		if (type === 1) {
			drawCircleElement(x, y, w);
		} else if (type === 2) {
			drawLineElement(x, y, w);
		} else if (type === 3) {
			drawArcElement(x, y, w, int(random(4)));
		} else if (type === 4) {
			drawGridElement(x, y, w);
		}

	}
}

function drawArcElement(x, y, w, dir) {
	let d = w * 2;
	let a1 = 0;
	let a2 = PI / 2;
	let xx = x - (w / 2);
	let yy = y - (w / 2);

	if (dir === 1) {
		a1 = PI / 2; a2 = PI;
		xx = x + (w / 2);
	} else if (dir === 2) {
		a1 = PI; a2 = PI * 1.5;
		xx = x + (w / 2); yy = y + (w / 2);
	} else if (dir === 3) {
		a1 = PI * 1.5; a2 = TAU;
		yy = y + (w / 2);
	}
	arc(xx, yy, d, d, a1, a2);


	if (w < height * 0.1) return;


	let n = int(random(3));
	let r = d / 2;
	for (let i = 0; i < n; i++) {
		let a = random(a1, a2);
		connectionNodes.push({ x: xx + r * cos(a), y: yy + r * sin(a), d: w });
	}
}

function drawCircleElement(x, y, w) {
	let d = w * random(0.1, 0.9);

	if (random() < 0.5) {
		d *= random(0.1, 1);
		x += ((w - d) / 2) * random(-1, 1)
		y += ((w - d) / 2) * random(-1, 1)
	}
	circle(x, y, d);

	let n = int(random(3));
	for (let i = 0; i < n; i++) {
		let a = random(TAU);
		let r = d / 2;
		let xx = x + r * cos(a);
		let yy = y + r * sin(a);
		connectionNodes.push({ x: xx, y: yy, d: w });
	}
}

function drawGridElement(x, y, w) {
	let n = ceil(random(1, 5));
	let ww = w / n;
	for (let i = 1; i < n; i++) {
		let pos = (i * ww) - (w / 2);
		line(x - w / 2, y + pos, x + w / 2, y + pos);
		line(x + pos, y - w / 2, x + pos, y + w / 2,);
		connectionNodes.push({ x: x + pos, y: y + (int(random(n)) * ww) - (w / 2), d: w });
	}
}

function drawLineElement(x, y, w) {
	let xx = x + w * random(-1, 1) * 0.4;
	let yy = y + w * random(-1, 1) * 0.4;
	line(xx, y - (w / 2), xx, y + (w / 2));
	line(x - (w / 2), yy, x + (w / 2), yy);
	connectionNodes.push({ x: xx, y: yy, d: w });
}

function applyRandomStyle() {
	let thickness = height * random(0.0011, 0.0002);
	let dashPattern = [0];
	let strokeColor = random(palette);

	if (random() < 0.5) {
		for (let i = 0; i < 5; i++) {
			dashPattern.push(height * random(0.002, 0.005));
		}
	}
	ctx.setLineDash(dashPattern);
	strokeWeight(thickness);
	stroke(strokeColor);
}

